/* Insert KEY_1(CMF_TRN_ABORT_START) of 'CMF_ITEM_NAME' MGCMTBLDAT */
BEGIN
	FOR REC IN (
		SELECT DISTINCT FACTORY FROM MWIPFACDEF
		MINUS
		SELECT DISTINCT FACTORY FROM MGCMTBLDAT 
		WHERE TABLE_NAME = 'CMF_ITEM_NAME'
		    AND KEY_1 = 'CMF_TRN_ABORT_START'
		) 
	LOOP

	INSERT INTO MGCMTBLDAT (FACTORY,TABLE_NAME,KEY_1,KEY_2,KEY_3,KEY_4,KEY_5,KEY_6,KEY_7,KEY_8,KEY_9,KEY_10,DATA_1,DATA_2,DATA_3,DATA_4,DATA_5,DATA_6,DATA_7,DATA_8,DATA_9,DATA_10,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) 
	VALUES (REC.FACTORY,'CMF_ITEM_NAME','CMF_TRN_ABORT_START',' ',' ',' ',' ',' ',' ',' ',' ',' ','Abort Start cmf','TRN','20',' ',' ',' ',' ',' ',' ',' ','ADMIN','20150801080000',' ',' ');

	END LOOP;
END ;
/

