/* Insert EVENT_ID MRASEVNDEF */
BEGIN
	FOR REC IN (
		SELECT DISTINCT FACTORY FROM MWIPFACDEF
		MINUS
		SELECT DISTINCT FACTORY FROM MRASEVNDEF 
		WHERE EVENT_ID = 'ABORT_START'
		) 
	LOOP

    INSERT INTO MRASEVNDEF 
    (FACTORY, EVENT_ID, EVENT_DESC, EVENT_GRP_1, EVENT_GRP_2, EVENT_GRP_3,
    EVENT_GRP_4, EVENT_GRP_5, EVENT_GRP_6, EVENT_GRP_7, EVENT_GRP_8, EVENT_GRP_9, EVENT_GRP_10,
