    CHK_FLAG_1, CHK_FLAG_2, CHK_FLAG_3, CHK_FLAG_4, CHK_FLAG_5, CHK_FLAG_6, CHK_FLAG_7, CHK_FLAG_8,
    CHK_FLAG_9, CHK_FLAG_10, CHK_STS_1, CHK_STS_2, CHK_STS_3, CHK_STS_4, CHK_STS_5, CHK_STS_6,
    CHK_STS_7, CHK_STS_8, CHK_STS_9, CHK_STS_10, CHG_FLAG_1, CHG_FLAG_2, CHG_FLAG_3, CHG_FLAG_4,
    CHG_FLAG_5, CHG_FLAG_6, CHG_FLAG_7, CHG_FLAG_8, CHG_FLAG_9, CHG_FLAG_10, CHG_STS_1, CHG_STS_2,
    CHG_STS_3, CHG_STS_4, CHG_STS_5, CHG_STS_6, CHG_STS_7, CHG_STS_8, CHG_STS_9, CHG_STS_10, TBL_1,
    TBL_2, TBL_3, TBL_4, TBL_5, TBL_6, TBL_7, TBL_8, TBL_9, TBL_10, COL_SET_ID, ALARM_FLAG,
    ALARM_MSG_ID, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME ) 
    VALUES 
    (REC.FACTORY, 'ABORT_START', 'Abort START_LOT', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' '
    , ' ', '=', 'U', 'N', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' '
    , ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' '
    , ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' '
    , ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 'ADMIN', '20150801080000', ' ', ' '); 

	END LOOP;
END ;
