BEGIN
	FOR REC IN (
		SELECT FACTORY, RES_ID FROM MRASRESEVN 
		WHERE EVENT_ID = 'START_LOT'
    MINUS
		SELECT FACTORY, RES_ID FROM MRASRESEVN 
		WHERE EVENT_ID = 'ABORT_START'
		) 
	LOOP

  INSERT INTO MRASRESEVN (FACTORY,RES_ID,EVENT_ID,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME,RES_TYPE)
  VALUES (REC.FACTORY,REC.RES_ID,'ABORT_START','MIGRATED',' ',' ',' ','M');

	END LOOP;
END ;
/

UPDATE MRASEVNDEF SET SYSTEM_FLAG = 'Y' WHERE EVENT_ID = 'ABORT_START';

